import "core-js/modules/es.array.push.js";
import CreateQuestion from "./CreateQuestion.vue";
import EditQuestion from "./EditQuestion.vue";
import DeleteQuestion from "./DeleteQuestion.vue";
import { ListQuestions } from "@/mixins/ListQuestions";
export default {
  props: {
    StoreObj: Object
  },
  components: {
    CreateQuestion,
    EditQuestion,
    DeleteQuestion
  },
  mixins: [ListQuestions],
  data: () => ({
    windowHeight: 0,
    DialogCreateQuestion: false,
    DialogEditQuestion: false,
    DialogDeleteQuestion: false,
    CategoryObj: {},
    EditQuestionObj: {},
    DeleteQuestionObj: {},
    ListAllQuestions: [],
    TableHeaders: [{
      title: "Question",
      value: "splay_question_text"
    }, {
      title: "Option A",
      value: "splay_option_1"
    }, {
      title: "Option B",
      value: "splay_option_2"
    }, {
      title: "Option C",
      value: "splay_option_3"
    }, {
      title: "Option D",
      value: "splay_option_4"
    }, {
      title: "Answer",
      value: "splay_correct_option"
    }, {
      title: "Actions",
      value: "actions"
    }]
  }),
  async mounted() {
    this.windowHeight = window.innerHeight - 265;
    await this.ListQuestionsMethod();
  },
  computed: {
    totalItems() {
      return this.ListAllQuestions.length;
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.ListAllQuestions.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.ListAllQuestions.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  methods: {
    QuestionPageEmit(Toggle) {
      this.$emit("clicked", Toggle);
    },
    OpenDialogCreateQuestion(item) {
      this.CategoryObj = item;
      this.DialogCreateQuestion = true;
    },
    DialogCreateQuestionEmit(Toggle) {
      this.DialogCreateQuestion = false;
      if (Toggle === 2) {
        this.ListQuestionsMethod();
      }
    },
    OpenDialogEditQuestion(item) {
      this.EditQuestionObj = item;
      this.DialogEditQuestion = true;
    },
    DialogEditQuestionEmit(Toggle) {
      this.DialogEditQuestion = false;
      if (Toggle === 2) {
        this.ListQuestionsMethod();
      }
    },
    OpenDialogDeleteQuestion(item) {
      this.DeleteQuestionObj = item;
      this.DialogDeleteQuestion = true;
    },
    DialogDeleteQuestionEmit(Toggle) {
      this.DialogDeleteQuestion = false;
      if (Toggle === 2) {
        this.ListQuestionsMethod();
      }
    }
  }
};
